def strategy(history, rng):
    n = len(history)
    if n == 0:
        return 'C'

    me = [h[0] for h in history]
    op = [h[1] for h in history]
    op_c = op.count('C')
    op_d = n - op_c

    if op_d == n:
        return 'D'

    our_defections = me.count('D')

    if our_defections == 0 and n >= 10:
        return 'D'

    opp_coop_after_our_def = 0
    opp_def_after_our_def = 0
    for i in range(n - 1):
        if me[i] == 'D':
            if op[i + 1] == 'C':
                opp_coop_after_our_def += 1
            else:
                opp_def_after_our_def += 1

    total_responses = opp_coop_after_our_def + opp_def_after_our_def
    if our_defections > 0 and total_responses == 0:
        return 'C'

    forgiveness = opp_coop_after_our_def / total_responses if total_responses > 0 else 0.0

    last_op = op[-1]
    last_me = me[-1]

    streak_d = 0
    for i in range(n - 1, -1, -1):
        if op[i] == 'D':
            streak_d += 1
        else:
            break

    if last_op == 'D':
        if streak_d >= 2:
            return 'D'
        if op_d * 2 > n:
            return 'D'
        if last_me == 'D':
            return 'C'
        if our_defections > 0 and forgiveness < 0.5:
            return 'C'
        return 'D'

    if last_me == 'D':
        return 'C'

    if n == 99:
        return 'D'

    if forgiveness > 0.5:
        if n % 10 == 0 and our_defections < n // 10:
            return 'D'

    if op_c * 5 >= n * 4:
        if n >= 95 and rng.random() < 0.25:
            return 'D'
        return 'C'

    if op_d * 2 > n:
        return 'D'

    return op[-1] if op else 'C'
